<script setup>
import {ref,computed,onMounted,onUnmounted} from 'vue'
import {useArcade} from '../stores/arcade'
import {accessoryPlacement} from '../data/accessories'
import DressedPartner from './DressedPartner.vue'
const emit=defineEmits(['close']),s=useArcade(),dialog=ref(null),stage=ref(null),busy=ref(false),error=ref(''),snapshot={formId:s.partner.formId,skinId:s.skin?.id??'',wear:s.data.pet.wear},key=JSON.stringify([snapshot.formId,snapshot.skinId,snapshot.wear]),fallback=accessoryPlacement(snapshot.formId,snapshot.wear,snapshot.skinId),defaults={x:fallback.x,y:fallback.y,scale:100,rotation:fallback.kind==='ornament'?9:fallback.rotation},draft=ref({...defaults,...s.data.pet.wearPositions?.[key]}),reset=ref(false);let dragging=null
const position=computed(()=>reset.value?defaults:draft.value)
function begin(e){if(busy.value||!e.target.closest('.partner-accessory'))return;e.preventDefault();const rect=stage.value.querySelector('.dressed-partner').getBoundingClientRect();draft.value={...position.value};reset.value=false;dragging={id:e.pointerId,x:e.clientX,y:e.clientY,position:{...draft.value},width:rect.width,height:rect.height};stage.value.setPointerCapture(e.pointerId)}
function move(e){if(!dragging||dragging.id!==e.pointerId)return;draft.value={...dragging.position,x:Math.max(0,Math.min(100,dragging.position.x+(e.clientX-dragging.x)/dragging.width*100)),y:Math.max(0,Math.min(100,dragging.position.y+(e.clientY-dragging.y)/dragging.height*100))}}
function stop(){dragging=null}
function change(axis,value){draft.value={...position.value,[axis]:Number(value)};reset.value=false}
function close(){if(!busy.value){dialog.value.close();emit('close')}}
async function save(){if(busy.value)return;busy.value=true;error.value='';try{await s.petAction('wear-position',{...snapshot,...position.value,reset:reset.value});busy.value=false;close()}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(()=>dialog.value.showModal());onUnmounted(()=>dialog.value?.close())
</script>
<template><dialog ref="dialog" class="wear-editor" aria-labelledby="wear-editor-title" @cancel.prevent="close"><header><h2 id="wear-editor-title">착용 아이템 편집</h2><button class="light" aria-label="위치 편집 닫기" :disabled="busy" @click="close">✕</button></header><p>모자·장식 위를 잡고 원하는 곳으로 옮기세요. 터치로도 움직일 수 있어요.</p><div ref="stage" class="wear-editor-stage" @pointerdown="begin" @pointermove="move" @pointerup="stop" @pointercancel="stop"><DressedPartner size="edit" editable :position-override="position"/></div><div class="wear-editor-controls"><label>가로 위치<input aria-label="아이템 가로 위치" type="range" min="0" max="100" step="1" :disabled="busy" :value="position.x" @input="change('x',$event.target.value)"/></label><label>세로 위치<input aria-label="아이템 세로 위치" type="range" min="0" max="100" step="1" :disabled="busy" :value="position.y" @input="change('y',$event.target.value)"/></label>
<label>크기 {{ position.scale }}%<input aria-label="아이템 크기" type="range" min="25" max="200" step="1" :disabled="busy" :value="position.scale" @input="change('scale',$event.target.value)"/></label>
<label>각도 {{ position.rotation }}°<input aria-label="아이템 각도" type="range" min="-180" max="180" step="1" :disabled="busy" :value="position.rotation" @input="change('rotation',$event.target.value)"/></label>
</div><small>현재 포켓몬 모습·스킨·아이템별로 저장됩니다. 저장 전에는 실제 착용 위치가 바뀌지 않아요.</small><p v-if="error" role="alert">{{error}}</p><div class="toolbar"><button class="light" :disabled="busy" @click="reset=true">기본 설정으로 초기화</button><button :disabled="busy" @click="save">{{busy?'저장 중…':'저장'}}</button><button class="light" :disabled="busy" @click="close">취소</button></div></dialog></template>
<style scoped>.wear-editor{box-sizing:border-box;width:min(590px,calc(100vw - 24px));max-height:92dvh;overflow:auto;padding:22px;border:3px solid var(--rpg-edge);border-radius:12px;background:var(--rpg-paper);color:var(--rpg-ink)}.wear-editor::backdrop{background:#17283f99}.wear-editor>header{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:0!important;border:0!important}.wear-editor h2{font-size:19px;margin:0}.wear-editor p{font-size:12px;line-height:1.8}.wear-editor-stage{height:320px;display:grid;place-items:center;border:2px solid var(--rpg-mid);background-color:var(--rpg-soft);background-image:linear-gradient(#ffffff60 1px,transparent 1px),linear-gradient(90deg,#ffffff60 1px,transparent 1px);background-size:20px 20px;overflow:hidden;touch-action:none;user-select:none}.wear-editor-controls{display:grid;grid-template-columns:1fr 1fr;gap:15px;margin:16px 0}.wear-editor-controls label{font-size:12px}.wear-editor-controls input{width:100%;box-sizing:border-box}.wear-editor small{font-size:10px;line-height:1.8;display:block}.wear-editor .toolbar{margin-top:18px;flex-wrap:wrap}.wear-editor .toolbar button{font-size:11px}@media(max-width:600px){.wear-editor{padding:16px}.wear-editor h2{font-size:16px}.wear-editor-stage{height:280px}.wear-editor-controls{grid-template-columns:1fr;gap:8px}}</style>
